{
  "per_column": [
    {
      "name": "interaction_collaboration_loss",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.7,
      "hallucination_observed": true,
      "rationale": "A meaningful thematic axis (loss of peer interaction) that gives a genuine grouping variable for predicting low satisfaction. Grounding is mostly sound, but ED-0001 was labeled 'cannot_replicate_peer_discussion' when the text only mentions camera freezing and missing raising a hand quietly, not peer discussion loss -- a mild overreach."
    },
    {
      "name": "subject_modality_fit",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.95,
      "hallucination_observed": false,
      "rationale": "Captures whether hands-on/performance subjects translate to remote format, a strong analytical axis distinct from other columns. ED-0002's 'hands_on_labs_or_experiments_lost' is a defensible reading (labs over video), and silent rows correctly marked not_present."
    },
    {
      "name": "instruction_quality",
      "analytical_usefulness": 0.85,
      "source_groundedness": 0.65,
      "hallucination_observed": true,
      "rationale": "Instruction quality is a plausible driver of satisfaction and offers a distinct grouping axis. However labels are shaky: ED-0003 'teacher can't tell when she's lost' was tagged 'teacher_overwhelmed_or_disorganized' (an inference beyond the text), and ED-0005 'cannot get juniors to participate' was tagged 'teacher_unresponsive_to_student_needs' though the text describes student non-participation, not teacher unresponsiveness -- a mislabel."
    },
    {
      "name": "engagement_sentiment",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.7,
      "hallucination_observed": true,
      "rationale": "Multi-level engagement signal is more useful than a bare sentiment flag and relevant to satisfaction. But ED-0001 tagged 'bored_or_disengaged' when the text shows frustration/technical struggle, not boredom -- a misread of the affective state."
    },
    {
      "name": "emotional_distress",
      "analytical_usefulness": 0.8,
      "source_groundedness": 0.75,
      "hallucination_observed": true,
      "rationale": "Emotional distress is a plausible predictor of low satisfaction. Values are largely grounded, though ED-0001 'frustration_with_format_or_parent' is a stretch from 'I miss raising my hand.' Note this column is near-duplicated by emotional_distress_signals."
    },
    {
      "name": "emotional_distress_signals",
      "analytical_usefulness": 0.15,
      "source_groundedness": 0.75,
      "hallucination_observed": true,
      "rationale": "Essentially a restatement of 'emotional_distress' -- same value vocabulary and near-identical row values (identical on all 5 samples). This redundancy adds no new analytical leverage, so usefulness is very low despite comparable grounding."
    }
  ],
  "analytical_usefulness": 0.68,
  "source_groundedness": 0.74,
  "rationale": "Most columns provide genuine, distinct thematic axes (collaboration loss, modality fit, instruction quality, engagement, distress) that are well-suited to predicting low learning satisfaction from open responses. The clear weakness is 'emotional_distress_signals', a near-exact duplicate of 'emotional_distress' that offers no new leverage. Grounding is generally sound with correct 'not_present' handling of silent rows, but several labels overreach the source text (e.g., inferring teacher disorganization, mislabeling frustration as boredom, or asserting peer-discussion loss where only technical issues are described), lowering groundedness modestly."
}

